import markColor from "../assets/radiant-mark.png";
import markMono from "../assets/radiant-mark-mono.png";

/**
 * The Radiant brand mark.
 *
 * Shows the official logo artwork (generated by scripts/build-icons.mjs from the
 * vendored master) rather than a letter in a coloured tile.
 *
 * Two variants, because the mark is two-tone: cyan + cream. Cream disappears on
 * a white background, so light mode uses a single-ink dark version. Both are
 * transparent and carry no background plate, so nothing reads as a "square".
 */
export default function BrandMark() {
  return (
    <span className="brand-mark" aria-hidden="true">
      <img className="brand-mark-colour" src={markColor} alt="" />
      <img className="brand-mark-mono" src={markMono} alt="" />
    </span>
  );
}
